using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing {
[Serializable] public class EngineUnit {public string id,modelId,owner,installedCarId;public WorkshopBuild build;}
[Serializable] public class EngineMove {public int rules=1,fee;public string engineId,donorId,receiverId;}
// The assembly, not the receiver car, owns the engine tune/induction/intake/exhaust hardware.
public static class EngineInventoryLedger {
 public static bool IsReceipt(TuneReceipt r)=>r.kind=="engine_pull"||r.kind=="engine_fit"||r.kind=="engine_transfer";
 static void Need(bool good,string reason){if(!good)throw new InvalidOperationException(reason);}
 public static WorkshopBuild Power(WorkshopBuild source){return new WorkshopBuild{naStage=source.naStage,induction=source.induction,inductionStage=source.inductionStage,coolingStage=source.coolingStage,intakeStage=source.intakeStage,exhaustStage=source.exhaustStage,sound=source.sound,soundStage=source.soundStage,engineModelId=null};}
 static void SetPower(WorkshopBuild target,WorkshopBuild source){target.naStage=source.naStage;target.induction=source.induction;target.inductionStage=source.inductionStage;target.coolingStage=source.coolingStage;target.intakeStage=source.intakeStage;target.exhaustStage=source.exhaustStage;target.sound=source.sound;target.soundStage=source.soundStage;}
 public static EngineUnit Find(FleetState f,string id)=>f.engines?.SingleOrDefault(e=>e.id==id)??throw new InvalidOperationException("Unknown engine identity");
 public static bool HasEngine(FleetState f,string carId){if(carId==FleetLedger.Loaner)return true;if(!f.inventoryReady)return true;var car=FleetLedger.Find(f,carId);return !string.IsNullOrEmpty(car.engineId)&&f.engines.Any(e=>e.id==car.engineId&&e.installedCarId==car.id&&e.owner==car.owner);}
 public static string ReadyCar(FleetState f)=>f.cars.FirstOrDefault(c=>c.owner=="player"&&HasEngine(f,c.id))?.id??FleetLedger.Loaner;
 public static void AddCar(FleetState f,FleetCar car){if(!f.inventoryReady)return;Need(string.IsNullOrEmpty(car.engineId),"New car already has an engine link");string id=car.id+":engine:original";Need(!f.engines.Any(e=>e.id==id),"Engine identity already exists");string model=string.IsNullOrEmpty(car.build.engineModelId)?VehicleLineup.Model(car):car.build.engineModelId;f.engines.Add(new EngineUnit{id=id,modelId=model,owner=car.owner,installedCarId=car.id,build=Power(car.build)});car.engineId=id;}
 public static void Ensure(FleetState f){if(f.inventoryReady)return;Need(f.engines==null||f.engines.Count==0,"Uninitialized inventory contains unsupported engines");Need(f.cars.All(c=>string.IsNullOrEmpty(c.engineId)),"Legacy car contains unsupported engine identity");f.engines=new List<EngineUnit>();f.inventoryReady=true;foreach(var car in f.cars)AddCar(f,car);}
 public static void Sync(FleetState f,FleetCar car){if(!f.inventoryReady)return;Need(HasEngine(f,car.id),"Cannot upgrade a car without an installed engine");var e=Find(f,car.engineId);e.build=Power(car.build);}
 public static void SyncOwners(FleetState f){if(!f.inventoryReady)return;foreach(var e in f.engines)if(!string.IsNullOrEmpty(e.installedCarId))e.owner=FleetLedger.Find(f,e.installedCarId).owner;ComponentInventoryLedger.SyncOwners(f);}
 public static void AfterFleet(FleetState f,TuneReceipt receipt){if(!f.inventoryReady)return;if(receipt.kind=="fleet_buy"||receipt.kind=="fleet_car"||receipt.kind=="duel_open")AddCar(f,f.cars[f.cars.Count-1]);SyncOwners(f);if(f.selectedId!=FleetLedger.Loaner&&!HasEngine(f,f.selectedId))f.selectedId=ReadyCar(f);}
 public static void ValidateLegacy(FleetState f){if(f==null)return;Need(!f.inventoryReady&&(f.engines==null||f.engines.Count==0)&&f.cars.All(c=>string.IsNullOrEmpty(c.engineId)),"Legacy fleet contains unsupported inventory data");f.engines=new List<EngineUnit>();}
 public static void Validate(FleetState f){Need(f.inventoryReady&&f.engines!=null,"Engine inventory not initialized");var ids=new HashSet<string>();foreach(var e in f.engines){Need(e!=null&&!string.IsNullOrEmpty(e.id)&&ids.Add(e.id)&&e.build!=null&&(e.owner=="player"||e.owner=="rival"),"Invalid engine inventory identity");Need(string.IsNullOrEmpty(e.build.engineModelId),"Engine snapshot cannot reference another engine");WorkshopCatalog.Load(e.modelId).Resolve(e.build);if(!string.IsNullOrEmpty(e.installedCarId)){var car=FleetLedger.Find(f,e.installedCarId);Need(car.engineId==e.id&&e.owner==car.owner&&JsonUtility.ToJson(Power(car.build))==JsonUtility.ToJson(e.build),"Installed engine disagrees with car/build/ownership history");Need((string.IsNullOrEmpty(car.build.engineModelId)?VehicleLineup.Model(car):car.build.engineModelId)==e.modelId,"Installed engine model disagrees with receiver build");}else Need(e.owner=="player","Only player-owned engines can be in storage");}foreach(var car in f.cars)if(!string.IsNullOrEmpty(car.engineId))Need(Find(f,car.engineId).installedCarId==car.id,"Engine cannot be linked to more than one car");if(f.selectedId!=FleetLedger.Loaner)Need(FleetLedger.Find(f,f.selectedId).owner=="player"&&HasEngine(f,f.selectedId),"Selected driving car is not ready/owned");else Need(!f.cars.Any(c=>c.owner=="player"&&HasEngine(f,c.id)),"Loaner is available only without a drive-ready owned car");}
 static FleetCar Owned(FleetState f,string id){Need(id!=FleetLedger.Loaner,"Recovery loaner cannot supply or receive engines");var c=FleetLedger.Find(f,id);Need(c.owner=="player","Only owned cars can supply or receive engines");return c;}
 // Version-one fitment rules are frozen for receipt replay. Later changes need another rules revision.
 static void CompatibleV1(FleetState f,EngineUnit engine,FleetCar receiver){string frame=VehicleLineup.Model(receiver),model=engine.modelId;Need(new[]{"car_finch","car_coda","car_vector","car_bastion","car_tempest"}.Contains(model),"No supported engine adapter kit");Need(frame!="car_finch"||model=="car_finch"||model=="car_coda","Finch bay only supports the matched compact four-cylinder adapters");if(model=="car_tempest"&&frame!="car_tempest"){Need(frame=="car_vector"||frame=="car_bastion","Tempest twin-turbo package requires a larger supported engine bay");Need(receiver.build.gearboxStage>=3&&receiver.build.brakeStage>=2&&receiver.build.tireStage>=2,"Tempest swap requires gearbox3, brakes2 and tires2");}float donor=WorkshopCatalog.Load(model).Resolve(engine.build).torque.Max(),stock=WorkshopCatalog.Load(frame).car.stock.torque.Max();float ratio=donor/stock;int stage=ratio>3?3:ratio>2.2f?2:ratio>1.4f?1:0;Need(receiver.build.gearboxStage>=stage,"Engine torque requires receiver gearbox Stage "+stage+" before fitting");}
 public static int FitFee(FleetState f,string engineId,string receiverId,bool transfer=false,string donorId=null){Ensure(f);Need(!f.HasPending,"Finish the committed race before moving engines");var receiver=Owned(f,receiverId);var e=Find(f,engineId);Need(e.owner=="player","That engine is not owned");if(transfer){var donor=Owned(f,donorId);Need(donor.id!=receiver.id&&donor.engineId==e.id&&e.installedCarId==donor.id,"Donor engine identity changed");}else Need(string.IsNullOrEmpty(e.installedCarId),"Engine is still installed; remove or transfer it first");CompatibleV1(f,e,receiver);return e.modelId==VehicleLineup.Model(receiver)?400:e.modelId=="car_tempest"?3500:e.modelId=="car_finch"||e.modelId=="car_coda"?1200:2000;}
 static void Detach(FleetState f,FleetCar car){var e=Find(f,car.engineId);e.build=Power(car.build);e.installedCarId="";car.engineId="";SetPower(car.build,new WorkshopBuild());car.build.engineModelId=null;}
 static void Attach(FleetState f,EngineUnit engine,FleetCar receiver){if(HasEngine(f,receiver.id))Detach(f,receiver);receiver.engineId=engine.id;engine.installedCarId=receiver.id;engine.owner=receiver.owner;SetPower(receiver.build,engine.build);receiver.build.engineModelId=engine.modelId==VehicleLineup.Model(receiver)?null:engine.modelId;f.selectedId=receiver.id;}
 public static void Replay(FleetState f,TuneReceipt r){Ensure(f);Need(!f.HasPending&&r.pathId=="inventory_v9"&&r.stage==0,"Invalid or race-locked engine transaction");var move=JsonUtility.FromJson<EngineMove>(r.fleetJson);Need(move!=null&&move.rules==1&&move.fee==r.credits&&r.partId==move.engineId&&r.configId==(string.IsNullOrEmpty(move.receiverId)?move.donorId:move.receiverId),"Invalid engine transaction terms");var e=Find(f,move.engineId);Need(e.owner=="player","Engine was not owned at time of transaction");if(r.kind=="engine_pull"){Need(r.credits==0&&string.IsNullOrEmpty(move.receiverId),"Invalid engine removal fee/target");var donor=Owned(f,move.donorId);Need(donor.engineId==e.id&&e.installedCarId==donor.id,"Engine removal source changed");Detach(f,donor);if(f.selectedId==donor.id)f.selectedId=ReadyCar(f);return;}Need(r.credits>0,"Engine fitting requires a positive historical labor payment");var receiver=Owned(f,move.receiverId);CompatibleV1(f,e,receiver);if(r.kind=="engine_transfer"){var donor=Owned(f,move.donorId);Need(donor.id!=receiver.id&&donor.engineId==e.id&&e.installedCarId==donor.id,"Transferred engine source changed");Detach(f,donor);}else{Need(r.kind=="engine_fit"&&string.IsNullOrEmpty(move.donorId)&&string.IsNullOrEmpty(e.installedCarId),"Engine must be stored before fitting");}Attach(f,e,receiver);}
}
}
